#file : 04_distribution_fits.py


import os
import numpy as np
import pandas as pd
import matplotlib.pyplot as plt
from scipy.stats import norm, laplace, cauchy, t as student_t

# Create folders for plots and parameter tables if they do not exist
os.makedirs("outputs/plots", exist_ok=True)
os.makedirs("outputs/tables", exist_ok=True)

# Load symmetrized residuals generated by Step 3
print("="*70, "\nLoading Symmetrized Residual Dataset\n", "="*70)
df = pd.read_csv("outputs/processed/symmetrized_residuals.csv")
print(df.head())


def fit_distributions(residuals):
    # Fit four distributions while fixing their location parameter at zero
    # Gaussian: fit standard deviation
    _, sigma = norm.fit(residuals, floc=0)

    # Laplace: fit scale parameter b
    loc_l, scale_l = laplace.fit(residuals, floc=0)

    # Cauchy: fit scale parameter gamma
    loc_c, scale_c = cauchy.fit(residuals, floc=0)

    # Student's-t: fit degrees of freedom and scale
    df_t, loc_t, scale_t = student_t.fit(residuals, floc=0)

    # Return the fitted parameters for all four distributions
    return {
        "Gaussian": (0, sigma),
        "Laplace": (loc_l, scale_l),
        "Cauchy": (loc_c, scale_c),
        "Student": (df_t, loc_t, scale_t)
    }


def plot_distribution(residuals, parameters, column):
    # Plot the residual histogram and fitted probability density curves
    plt.figure(figsize=(9, 6))

    # Show the observed symmetrized residual distribution
    plt.hist(
        residuals, bins=30, density=True, alpha=0.4,
        color="gray", edgecolor="black",
        label="Symmetrized Residuals"
    )

    # Generate x-values for smooth distribution curves
    x = np.linspace(residuals.min() - 1, residuals.max() + 1, 2000)

    # Plot the fitted Gaussian distribution
    _, sigma = parameters["Gaussian"]
    plt.plot(
        x, norm.pdf(x, 0, sigma), linewidth=2.5,
        linestyle="-", label=f"Gaussian ($\\sigma$={sigma:.3f})"
    )

    # Plot the fitted Laplace distribution
    _, scale_l = parameters["Laplace"]
    plt.plot(
        x, laplace.pdf(x, 0, scale_l), linewidth=2.5,
        linestyle="--", label=f"Laplace ($b$={scale_l:.3f})"
    )

    # Plot the fitted Cauchy distribution
    _, scale_c = parameters["Cauchy"]
    plt.plot(
        x, cauchy.pdf(x, 0, scale_c), linewidth=2.5,
        linestyle=":", label=f"Cauchy ($\\gamma$={scale_c:.3f})"
    )

    # Plot the fitted Student's-t distribution
    nu, _, scale_t = parameters["Student"]
    plt.plot(
        x, student_t.pdf(x, nu, 0, scale_t), linewidth=2.5,
        linestyle="-.",
        label=f"Student-t ($\\nu$={nu:.2f}, $s$={scale_t:.3f})"
    )

    # Make the plot title readable using the residual column name
    clean_title = column.replace("Sym_Residual_", "").replace("_", " ")

    # Add labels, title, legend, and grid
    plt.xlabel("Symmetrized Error Residual ($N_\\sigma$)", fontsize=12)
    plt.ylabel("Probability Density", fontsize=12)
    plt.title(
        f"Symmetrized Error Distribution Fits: {clean_title}",
        fontsize=13, fontweight="bold"
    )
    plt.legend(fontsize=10, loc="upper right")
    plt.grid(True, linestyle=":", alpha=0.6)
    plt.xlim(-6, 6)
    plt.tight_layout()

    # Save the plot as a high-resolution PNG
    plt.savefig(f"outputs/plots/symmetrized_{column}_fit.png", dpi=300)
    plt.close()


def save_parameters(parameters, column):
    # Store fitted scale parameters and Student's-t degrees of freedom in a CSV
    summary = pd.DataFrame({
        "Distribution": ["Gaussian", "Laplace", "Cauchy", "Student-t"],
        "Location (fixed)": [0.0, 0.0, 0.0, 0.0],
        "Scale Parameter": [
            parameters["Gaussian"][1],
            parameters["Laplace"][1],
            parameters["Cauchy"][1],
            parameters["Student"][2]
        ],
        "Degrees of Freedom (nu)": [
            np.nan, np.nan, np.nan, parameters["Student"][0]
        ]
    })

    # Save one parameter table for each residual definition
    summary.to_csv(
        f"outputs/tables/symmetrized_{column}_parameters.csv",
        index=False
    )


def print_summary(parameters):
    # Print fitted parameters so they can be checked in the terminal
    print("\n" + "-"*50, "\nFitted Scale Parameters (Location locked at 0.0)\n", "-"*50)
    print(f"Gaussian Scale (std dev) : {parameters['Gaussian'][1]:.4f}")
    print(f"Laplace Scale (b)        : {parameters['Laplace'][1]:.4f}")
    print(f"Cauchy Scale (gamma)     : {parameters['Cauchy'][1]:.4f}")
    print(
        f"Student-t (nu, scale s)  : "
        f"nu={parameters['Student'][0]:.2f}, "
        f"s={parameters['Student'][2]:.4f}"
    )
    print("-"*50)


# Select the four main residual definitions, including wm+ and wm-
residual_columns = [
    "Sym_Residual_Mean",
    "Sym_Residual_Weighted_Plus",
    "Sym_Residual_Weighted_Minus",
    "Sym_Residual_Median"
]

# Include the older weighted-residual column if it exists
# This maintains compatibility with previous scripts
if "Sym_Residual_Weighted" in df.columns and "Sym_Residual_Weighted" not in residual_columns:
    residual_columns.append("Sym_Residual_Weighted")


# Process each available residual definition separately
for column in residual_columns:

    # Skip columns that are not present in the input file
    if column not in df.columns:
        print(f"\nSkipping {column} (not found in dataset).")
        continue

    print("\n" + "="*70, f"\nProcessing Symmetrized Fits for: {column}\n", "="*70)

    # Remove missing values before fitting distributions
    residuals = df[column].dropna()
    print("Number of Residuals (2N):", len(residuals))

    # Skip the column if it contains no valid residuals
    if len(residuals) == 0:
        print(f"Warning: No valid data for {column}. Skipping.")
        continue

    # Fit all four distributions to the selected residuals
    parameters = fit_distributions(residuals)

    # Display results, create the plot, and save the fitted parameters
    print_summary(parameters)
    plot_distribution(residuals, parameters, column)
    save_parameters(parameters, column)

    print(f"--> {column} distribution fitting complete.")


# Confirm that the script has finished processing
print("\n" + "="*70 + "\n04_distribution_fits.py Completed Successfully\n" + "="*70)
